import assert from 'node:assert/strict';

// UI contract checks for the actual HTML generated by app.js. Browser layout
// verification is intentionally separate from this DOM-stub smoke test.
const listeners = {};
const store = new Map();
const root = {innerHTML:'',addEventListener(type,handler){listeners[type]=handler;}};
const modal = {innerHTML:'',replaceChildren(){this.innerHTML='';}};
const documentElement = {dataset:{},lang:'id'};
globalThis.localStorage = {
  getItem:key=>store.get(key)??null,
  setItem:(key,value)=>store.set(key,String(value)),
  removeItem:key=>store.delete(key)
};
globalThis.window = {scrollTo(){},addEventListener(){}};
globalThis.location = {hash:'#home'};
globalThis.document = {
  documentElement,
  getElementById(id){return ({app:root,'modal-root':modal})[id]||null;},
  querySelector(selector){
    if(selector==='meta[name="theme-color"]')return {setAttribute(){}};
    if(selector==='.modal-panel')return {focus(){}};
    return null;
  },
  body:{classList:{add(){},remove(){}},appendChild(){}},
  createElement(){return {style:{},remove(){},setAttribute(){}};},
  addEventListener(){}
};
globalThis.FormData = class {constructor(form){this.form=form;}entries(){return Object.entries(this.form.fields||{});}};
await import('../src/app.js');
function click(data, attr='action') {
  const el={dataset:data,classList:{contains(){return false;}}};
  listeners.click({target:{closest(selector){return selector===`[data-${attr}]`?el:null;}}});
}
async function submit(id, fields) {
  await listeners.submit({preventDefault(){},target:{id,fields,querySelector(){return null;}}});
}
click({auth:'register'},'auth');
await submit('auth-form',{name:'Rina',email:'rina@test.local',username:'rina',password:'password-123',confirm:'password-123',campus:'Universitas Contoh',nim:''});
assert.match(root.innerHTML,/gm-feed-filter/,'Explore has mobile filter control');
assert.match(root.innerHTML,/gm-fab-tooltip/,'Mobile action has meaningful label');
assert.match(root.innerHTML,/Buat konten/);
click({page:'profile'},'page');
assert.match(root.innerHTML,/data-profile-tab="materials"/,'Own material archive tab exists');
click({profileTab:'materials'},'profile-tab');
assert.match(root.innerHTML,/Tidak ada materi yang dibagikan/);
click({page:'learning'},'page');
click({action:'create-material'});
await submit('material-form',{title:'Materi Aljabar',summary:'Pengantar operasi matriks',category:'Desain Produk',duration:'35',chapter_0:'Operasi dasar'});
click({page:'profile'},'page');
click({profileTab:'materials'},'profile-tab');
assert.match(root.innerHTML,/Materi Aljabar/,'New material is visible in private archive');
assert.match(root.innerHTML,/data-action="edit-material"/);
assert.match(root.innerHTML,/data-action="material-delete"/);
click({page:'settings'},'page');
for(const text of ['settings-email-form','settings-password-form','set-language','set-theme','campus-request','https://wa.me/6282374751806']){
  if(text==='campus-request')continue; // Requires a registered local campus.
  assert.ok(root.innerHTML.includes(text),`Settings includes ${text}`);
}
click({action:'set-theme',value:'dark'});
assert.equal(documentElement.dataset.theme,'dark');
click({action:'set-language',value:'en'});
assert.equal(documentElement.lang,'en');
click({action:'account-menu'});
assert.match(root.innerHTML,/data-action="logout">/,'Account menu exposes Log out');
click({page:'opportunity'},'page');
assert.match(root.innerHTML,/data-action="xp-share"/,'Opportunity keeps the hero share button');
assert.doesNotMatch(root.innerHTML,/xp-share-fab/,'Opportunity has no redundant floating button');
click({action:'account-menu'});
click({action:'logout'});
click({action:'logout-now'});
click({auth:'login'},'auth');
assert.match(root.innerHTML,/Username atau email/);
await submit('auth-form',{username:'rina@test.local',password:'password-123'});
assert.match(root.innerHTML,/Halo, Rina/,'Sign in using registered email must work');
click({page:'settings'},'page');
await submit('settings-email-form',{email:'rina-new@test.local',current:'password-123'});
assert.match(root.innerHTML,/rina-new@test.local/,'New email must appear in Settings');
click({action:'logout'});click({action:'logout-now'});click({auth:'login'},'auth');
await submit('auth-form',{username:'rina-new@test.local',password:'password-123'});
assert.match(root.innerHTML,/Halo, Rina/,'Sign in using changed email must work');
console.log('PASS: mobile controls, archive, settings, language/theme, account menu, Opportunity CTA and email login');
